      "check_id": "CKV_AWS_273",
      "title": "Direct AWS IAM user creation instead of SSO-managed access",
      "resource": "aws_iam_user.privesc11-PutGroupPolicy-user",
      "severity": "MEDIUM",
      "explanation": "This resource creates a persistent IAM user directly in AWS rather than managing human access through SSO. Direct IAM users increase the risk of long-lived credentials and decentralized identity lifecycle management."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc11-PutGroupPolicy-user\" {\n  count = 0\n\n  name = \"privesc11-PutGroupPolicy-user\"\n  path = \"/\"\n}\n",
  "fix_summary": "Disabled creation of the direct IAM user while retaining the existing resource declaration. Access should instead be provisioned through the organization's SSO system."
}
